with gaps as (select *, case when lag(paid_at) over (partition by status order by paid_at asc, id asc) is null or paid_at > lag(paid_at) over (partition by status order by paid_at asc, id asc) + interval '30' day then 1 else 0 end as session_start_flag from payments) select *, sum(session_start_flag) over (partition by status order by paid_at asc, id asc rows between unbounded preceding and current row) as session_no from gaps
